import csv
import io
import re
from typing import List, Dict, Any


def _is_blank(row: List[str]) -> bool:
    return not row or all(value.strip() == "" for value in row)


def _looks_like_month_date(value: str) -> bool:
    return bool(re.match(
        r"^\s*(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|"
        r"jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|"
        r"oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+\d{1,2}\s*$",
        value,
        re.I,
    ))


def _looks_like_year(value: str) -> bool:
    return bool(re.match(r"^\s*\d{4}\s*$", value))


def _column_kind(name: str) -> str:
    value = re.sub(r"[^a-z0-9]+", "", name.lower())
    if any(token in value for token in ("date", "day")):
        return "date"
    if any(token in value for token in ("time", "hour")):
        return "time"
    if any(token in value for token in ("qty", "quantity", "count", "number", "units")):
        return "integer"
    if any(token in value for token in ("price", "cost", "amount", "value", "total")):
        return "number"
    if any(token in value for token in ("url", "uri", "link", "website", "email")):
        return "url"
    if any(token in value for token in ("id", "code", "sku", "key")):
        return "identifier"
    return "text"


def _kind_score(value: str, kind: str) -> int:
    text = value.strip()
    if kind == "text":
        return 0
    if kind == "date":
        if re.match(r"^\d{1,4}[/-]\d{1,2}[/-]\d{1,4}$", text):
            return 3
        if re.match(r"^[A-Za-z]+\s+\d{1,2},?\s+\d{4}$", text):
            return 3
        return -3
    if kind == "time":
        return 3 if re.match(r"^\d{1,2}:\d{2}(?::\d{2})?$", text) else -3
    if kind == "integer":
        return 3 if re.match(r"^[+-]?\d+$", text) else -3
    if kind == "number":
        return 3 if re.match(r"^[+-]?\s*(?:[$€£¥])?\s*\d+(?:[.,]\d+)?%?$", text) else -3
    if kind == "url":
        return 3 if re.match(r"^(?:https?|ftp)://", text, re.I) else -3
    if kind == "identifier":
        return 2 if re.match(r"^[A-Za-z0-9._/-]+$", text) else -2
    return 0


def _merge_best(row: List[str], width: int, kinds: List[str]) -> List[str]:
    result = list(row)
    while len(result) > width:
        best_index = 0
        best_score = None
        for index in range(len(result) - 1):
            candidate = result[:index] + [result[index] + "," + result[index + 1]] + result[index + 2:]
            score = 0
            for column, value in enumerate(candidate[:width]):
                score += _kind_score(value, kinds[column] if column < len(kinds) else "text")
            if index < width:
                merged_kind = kinds[index] if index < len(kinds) else "text"
                score += _kind_score(candidate[index], merged_kind)
            if "," in candidate[index] and index < len(kinds):
                if kinds[index] in ("date", "time", "integer", "number", "url", "identifier"):
                    score -= 2
            score -= max(0, len(candidate) - width)
            if best_score is None or score > best_score:
                best_score = score
                best_index = index
        result = (
            result[:best_index]
            + [result[best_index] + "," + result[best_index + 1]]
            + result[best_index + 2:]
        )
    return result


def _normalize_row(row: List[str], width: int, kinds: List[str]) -> List[str]:
    values = list(row)
    if len(values) > width:
        if (
            len(values) >= 2
            and _looks_like_month_date(values[0])
            and _looks_like_year(values[1])
        ):
            values = [values[0] + "," + values[1]] + values[2:]
        values = _merge_best(values, width, kinds)
    if len(values) < width:
        values.extend([""] * (width - len(values)))
    return values[:width]


def parse_csv(raw_csv: str):
    width = 9
    source = raw_csv
    if source.startswith("\ufeff"):
        source = source[1:]

    try:
        reader = csv.reader(
            io.StringIO(source, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        parsed = [list(row) for row in reader]
    except csv.Error:
        parsed = []
        for line in source.splitlines():
            parsed.append(next(csv.reader([line], delimiter=",", quotechar='"', strict=False)))

    nonblank = [(index, row) for index, row in enumerate(parsed) if not _is_blank(row)]
    if not nonblank:
        return {"columns": [], "rows": []}

    header_index = None
    header_score = -1
    for index, row in nonblank:
        if len(row) != width:
            continue
        score = 0
        for value in row:
            text = value.strip()
            if re.match(r"^[A-Za-z][A-Za-z0-9 _-]*$", text):
                score += 2
            if re.search(r"[A-Za-z]", text) and not re.search(r"[,/$:]", text):
                score += 1
        if score > header_score:
            header_score = score
            header_index = index

    if header_index is None:
        header_index = nonblank[0][0]

    header = _normalize_row(parsed[header_index], width, ["text"] * width)
    kinds = [_column_kind(value) for value in header]

    rows: List[List[str]] = []
    for row in parsed[header_index + 1:]:
        if _is_blank(row):
            continue
        rows.append(_normalize_row(row, width, kinds))

    return {"columns": header, "rows": rows}
